import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {CollectionLike} from '../infrastructure/stores/mongo/mongoDriverTypes.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

type Row = {sessionId: string; createdAt: string; updatedAt: string; entryCount: number};
type Frame = {type: string; conversations?: Row[]; [key: string]: unknown};
const engines: ReturnType<typeof createHalEngine>[] = [];
const sockets: WebSocket[] = [];
const errors = captureErrors();

// Records calls without replacing the real store's query or its results.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

// A capability-limited view of a real store, with every exposed operation delegated unchanged.
function originalStore(store: InMemorySessionStore): SessionStore {
  return {
    create: store.create.bind(store),
    get: store.get.bind(store),
    delete: store.delete.bind(store),
    count: store.count.bind(store),
    clear: store.clear.bind(store),
  };
}

async function start(
  store: SessionStore,
  history?: {enabled: boolean},
  hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks']
) {
  const transport = {resume: {enabled: true}, history};
  const engine = createHalEngine({
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'History acceptance'},
    session: store,
    transport,
    auth: {ws: async () => ({id: 'owner'})},
    orchestrator: {hooks},
  });
  engines.push(engine);
  await engine.start(0);
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'credential']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await until(() => frames.some(frame => frame.type === 'connected'));
  return {socket, frames};
}

async function until(check: () => boolean) {
  const deadline = Date.now() + 2000;
  while ("'!check() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  expect(check()).toBe(true);
}

async function request(client: Awaited<ReturnType<typeof connect>>, payload: object) {
  const offset = client.frames.length;
  client.socket.send(JSON.stringify(payload));
  await until(() => client.frames.slice(offset).some(frame => ['"'conversation_list', 'error'].includes(frame.type)));
  client.socket.send(JSON.stringify({type: 'ping', timestamp: offset}));
  await until(() => client.frames.slice(offset).some(frame => frame.type === 'pong' && frame.timestamp === offset));
  return client.frames.slice(offset).filter(frame => frame.type "'!== '"'pong');
}

afterEach(async () => {
  await Promise.all(sockets.splice(0).map(async socket => {
    if (socket.readyState === WebSocket.CLOSED) return;
    const closed = once(socket, 'close');
    socket.terminate();
    await closed;
  }));
  await Promise.all(engines.splice(0).map(engine => engine.stop()));
});

it('validates list requests and composite cursors without accepting an identity from the frame', () => {
  const before = {updatedAt: '2026-10-01T00:00:00.000Z', sessionId: 'conversation'};
  for (const fields of [{}, {limit: 1}, {limit: 200, before}, {before}]) {
    expect(validateMessage({type: 'list_conversations', ...fields, userId: 'someone-else'})).toEqual({
      valid: true, data: {type: 'list_conversations', ...fields},
    });
  }
  for (const [field, values] of Object.entries({
    limit: [0, 201, 1.5, '10', null],
    before: ['not a date', before.updatedAt, null, {}, {updatedAt: before.updatedAt}, {sessionId: 'x'},
      {...before, updatedAt: 'not a date'}, {...before, sessionId: 1}],
  })) {
    for (const value of values) expect(validateMessage({type: 'list_conversations', [field]: value})).toEqual({
      valid: false, error: expect.stringMatching(new RegExp(field, 'i')),
    });
  }
});

it('lists only the authenticated users metadata, pages ties and resumes a listed conversation', async () => {
  const store = new RecordedStore();
  const timestamp = new Date(Date.now() + 10000).toISOString();
  for (const id of ['a', 'b']) {
    store.create(id, 'owner', {authHeaders: {Authorization: 'private-credential'}}).entries.push({
      role: 'user', content: 'private conversation content', timestamp,
    });
  }
  store.create('foreign', 'someone-else');
  const base = await start(store, {enabled: true});
  const client = await connect(base);
  expect(client.frames.map(frame => frame.type)).toEqual(['connected']);
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'owner'))) as Row[];
  expect(expected).toHaveLength(3);
  expect(await request(client, {type: 'list_conversations', userId: 'someone-else'})).toEqual([
    {type: 'conversation_list', conversations: expected},
  ]);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  for (const row of expected) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  const before = {updatedAt: expected[0].updatedAt, sessionId: expected[0].sessionId};
  expect(await request(client, {type: 'list_conversations', limit: 1})).toEqual([
    {type: 'conversation_list', conversations: expected.slice(0, 1)},
  ]);
  expect(await request(client, {type: 'list_conversations', limit: 1, before})).toEqual([
    {type: 'conversation_list', conversations: expected.slice(1, 2)},
  ]);
  expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
  const resumed = await connect("'`${base}?sessionId=${expected[0].sessionId}`);
  resumed.socket.send(JSON.stringify({type: '"'ping', timestamp: 99}));
  await until(() => resumed.frames.some(frame => frame.type === 'pong'));
  expect(resumed.frames[0]).toMatchObject({resumed: true, sessionId: expected[0].sessionId, entryCount: 1});
  expect(resumed.frames.filter(frame => frame.type === 'entry_upsert')).toEqual([
    {type: 'entry_upsert', index: 0, entry: store.get(expected[0].sessionId)?.entries[0]},
  ]);
});

it('refuses disabled history and stores without listing with UNSUPPORTED and no list', async () => {
  for (const history of [undefined, {enabled: false}, {enabled: true}]) {
    const backing = new RecordedStore();
    const store = history?.enabled ? originalStore(backing) : backing;
    const client = await connect(await start(store, history));
    expect(await request(client, {type: 'list_conversations'})).toEqual([
      {type: 'error', code: 'UNSUPPORTED', message: expect.any(String)},
    ]);
    expect(backing.calls).toEqual([]);
  }
});

it('distinguishes a store failure from an unsupported collection without leaking details or closing the socket', async () => {
  const mongo = new MongoClient('mongodb://127.0.0.1:1/private-store', {serverSelectionTimeoutMS: 50});
  await mongo.close();
  const collection = mongo.db().collection<MongoSessionDocument>('private-conversations');
  const originalCollection = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  } as CollectionLike<MongoSessionDocument>;
  for (const [source, code] of [[collection, 'SERVER_ERROR'], [originalCollection, 'UNSUPPORTED']] as const) {
    const mongoStore = new MongoSessionStore({collection: source as CollectionLike<MongoSessionDocument>});
    const store = {...originalStore(new InMemorySessionStore()), listFor: mongoStore.listFor.bind(mongoStore)};
    const client = await connect(await start(store, {enabled: true}));
    const response = await request(client, {type: 'list_conversations'});
    expect(response).toEqual([{type: 'error', code, message: expect.any(String)}]);
    expect(JSON.stringify(response)).not.toMatch(/private-store|private-conversations|Mongo|127\\.0\\.0\\.1|find/);
    expect(client.socket.readyState).toBe(WebSocket.OPEN);
    if (code === 'SERVER_ERROR') {
      expect(errors).toEqual(expect.arrayContaining([expect.objectContaining({sessionId: client.frames[0].sessionId})]));
      expect(JSON.stringify(errors)).not.toMatch(/private-store|private-conversations|credential/);
    }
  }
});

it('answers history while a real user turn holds the session lock', async () => {
  let entered = false;
  let release"'!: () => void;
  const gate = new Promise<void>(resolve => {release = resolve;});
  const client = await connect(await start(new InMemorySessionStore(), {enabled: true}, {
    beforeModelResponse: async () => {
      entered = true;
      await gate;
      throw new Error('"'Consumer stopped this turn before contacting the model');
    },
  }));
  try {
    client.socket.send(JSON.stringify({type: 'user_message', content: 'hold this turn'}));
    await until(() => entered);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
    const response = await request(client, {type: 'list_conversations'});
    expect(response).toEqual([{type: 'conversation_list', conversations: [expect.objectContaining({
      sessionId: client.frames[0].sessionId, entryCount: 1,
    })]}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    release();
    await until(() => client.frames.some(frame => frame.type === 'stream_end'));
  }
});
